type clientStreamingServerImpl[Req, Res any] struct {
	ServerStream
}

func (c *clientStreamingServerImpl[Req, Res]) Recv(ctx context.Context) (*Req, error) {
	var req Req
	if err := c.ServerStream.RecvMsg(ctx, &req); err != nil {
		return nil, err
	}
	return &req, nil
}

func (c *clientStreamingServerImpl[Req, Res]) SendAndClose(ctx context.Context, res *Res) error {
	return c.ServerStream.SendMsg(ctx, res)
}

// NewClientStreamingServer creates a ClientStreamingServer from a ServerStream
func NewClientStreamingServer[Req, Res any](st ServerStream) ClientStreamingServer[Req, Res] {
