// Package transport provides predefined transport protocol.
package transport

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	TTHeader Protocol = 1 << iota
	Framed
	HTTP
	GRPC
	HESSIAN2
	STREAMING

	TTHeaderFramed = TTHeader | Framed
)

// Dedicated streaming protocol constants
const (
	TTHeaderStreaming Protocol = 64
	GRPCStreaming     Protocol = 128
)

// Default is the default transport protocol.
const Default = Framed

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	// Check for single flags first
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeader:
		return "TTHeader"
	case Framed:
		return "Framed"
	case HTTP:
		return "HTTP"
	case GRPC:
		return "GRPC"
	case HESSIAN2:
		return "Hessian2"
	case STREAMING:
		return "STREAMING"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	case TTHeaderFramed:
		return "TTHeaderFramed"
	}

	// Handle composite protocols (pipe-separated in ascending order)
	var parts []string
	flags := []struct {
		val  Protocol
		name string
	}{
		{TTHeader, "TTHeader"},
		{Framed, "Framed"},
		{HTTP, "HTTP"},
		{GRPC, "GRPC"},
		{HESSIAN2, "Hessian2"},
		{STREAMING, "STREAMING"},
	}

	for _, flag := range flags {
		if tp&flag.val != 0 {
			parts = append(parts, flag.name)
		}
	}

	if len(parts) > 0 {
		result := parts[0]
		for i := 1; i < len(parts); i++ {
			result += "|" + parts[i]
		}
		return result
	}

	return Unknown
}
