// On validation failure, it logs a hex dump of the frame header for diagnostics.
func readAndCheckFrameHeader(r netpoll.Reader) (http2.FrameHeader, error) {
	fh, err := readFrameHeader(r)
	if err != nil {
		return fh, err
	}

	// Validate frame header fields
	var validationErr error

	// Check for unreasonably large frame length (max frame size is typically 16MB)
	if fh.Length > 16*1024*1024 {
		validationErr = fmt.Errorf("frame length %d exceeds maximum (16MB)", fh.Length)
	}

	// Check for unknown frame types (types > 9 are not defined in HTTP/2)
	if fh.Type > 9 {
		validationErr = fmt.Errorf("unknown frame type: %d", fh.Type)
	}

	// If validation failed, log hex dump for diagnostics
	if validationErr != nil {
		// Reconstruct the frame header bytes for hex dump
		headerBytes := make([]byte, frameHeaderLen)
		headerBytes[0] = byte(fh.Length >> 16)
		headerBytes[1] = byte(fh.Length >> 8)
		headerBytes[2] = byte(fh.Length)
		headerBytes[3] = byte(fh.Type)
		headerBytes[4] = byte(fh.Flags)
