	buf, err := fr.reader.Next(frameHeaderLen)
	if err != nil {
		return http2.FrameHeader{}, err
	}

	// Parse frame header
	fh := http2.FrameHeader{
		Length:   uint32(buf[0])<<16 | uint32(buf[1])<<8 | uint32(buf[2]),
		Type:     http2.FrameType(buf[3]),
		Flags:    http2.Flags(buf[4]),
		StreamID: binary.BigEndian.Uint32(buf[5:]) & (1<<31 - 1),
	}

	// Validate frame size against maxReadSize
	if fh.Length > fr.maxReadSize {
		// Create hex-formatted error with first 4 bytes and second 4 bytes
		first4Bytes := buf[:4]
		second4Bytes := buf[4:8]

		hexDump := fmt.Sprintf("% x", buf)
		klog.Warnf("[gRPC Frame Validation] Frame size %d exceeds maxReadSize %d | Hex: [%s] | Type=%d Flags=0x%x StreamID=%d",
			fh.Length, fr.maxReadSize, hexDump, fh.Type, fh.Flags, fh.StreamID)

		return fh, fmt.Errorf("%s or invalid frame (first4Bytes=%#x, second4Bytes=%#x)", 
			http2.ErrFrameTooLarge, first4Bytes, second4Bytes)
	}

	return fh, nil
}

